import hashlib
import os

from flask import Flask, Response, abort, jsonify, request

from .config import ServerConfig


def create_app(config: ServerConfig) -> Flask:
    app = Flask(__name__)
    app.config["SYNCBOX_CONFIG"] = config

    @app.get("/healthz")
    def healthz():
        return "", 200

    @app.put("/blobs/<path:key>")
    def put_blob(key):
        data = request.get_data()

        path = os.path.join(config.data_dir, key)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as f:
            f.write(data)

        sha256 = hashlib.sha256(data).hexdigest()
        return jsonify(key=key, sha256=sha256, size=len(data)), 201

    @app.get("/blobs/<path:key>")
    def get_blob(key):
        path = os.path.join(config.data_dir, key)
        if not os.path.isfile(path):
            abort(404)

        with open(path, "rb") as f:
            data = f.read()
        return Response(data, mimetype="application/octet-stream")

    return app
